package org.dromara.sports.registration.service;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;
@Service @RequiredArgsConstructor
public class RegistrationActionProvider implements CapabilityProvider {
 private final RegistrationService registrations;private final ScopedJdbc db;private final ObjectMapper json;
 private static final Set<String> READS=Set.of("asp_registration","asp_registration_member","asp_competition_unit","asp_competition_type","asp_event","asp_event_field","asp_org_field","asp_entry_field_value","asp_account","asp_person","asp_team","asp_team_member","asp_capacity_pool","asp_roster_member","asp_roster_version","asp_declaration_ack","asp_fee_obligation","asp_fee_policy","asp_event_payment_config","asp_registration_submit_key","asp_idempotency","asp_qualification_review","asp_payment_action","asp_payment_exception","asp_payment_allocation");
 // Formal submission freezes each member's field label/type/options in the same
 // transaction. Declaring this write does not grant unrelated personal-profile edits.
 private static final Set<String> WRITES=Set.of("asp_registration","asp_registration_member","asp_entry_field_value","asp_capacity_pool","asp_roster_member","asp_roster_version","asp_fee_obligation","asp_registration_submit_key","asp_idempotency","asp_qualification_review","asp_notification","asp_team_room","asp_event");
 public List<CapabilityDefinition> capabilities(){return List.of(cap("registration.mine","查询我的报名及待办",false,false,"eventId?"),cap("registration.create","建立本人报名草稿",true,false,"unitId","teamId?"),cap("registration.submit","确认冻结名单规则费用并正式报名",true,true,"registrationId","expectedVersion"));}
 private CapabilityDefinition cap(String c,String t,boolean write,boolean confirm,String...f){return capability(json,c,t,"asp_registration",true,confirm,Set.of("platform"),"",READS,write?WRITES:Set.of(),f);}
 public JsonNode preview(String c,JsonNode in){var mine=registrations.listMine(optionalId(in,"eventId"));if(!in.has("registrationId"))return json.valueToTree(mine);long id=id(in,"registrationId");var e=mine.stream().filter(r->r.id().equals(id)&&r.canManage()).findFirst().orElseThrow(()->fail("请由本单报名管理人办理",403));var n=json.createObjectNode();n.set("registration",json.valueToTree(e));n.set("version",json.valueToTree(db.one("SELECT version FROM asp_registration WHERE id=? FOR UPDATE",id).get("version")));n.set("feePolicy",safeJson(json,db.list("SELECT p.id,p.revision,p.amount,p.payment_mode,p.pay_instruction,p.qr_file_id FROM asp_fee_policy p JOIN asp_registration r ON r.unit_id=p.unit_id WHERE r.id=? AND p.status='active' ORDER BY p.id",id)));n.set("answers",safeJson(json,db.list("SELECT v.* FROM asp_entry_field_value v JOIN asp_registration_member m ON m.id=v.registration_member_id WHERE m.registration_id=? ORDER BY v.id",id)));n.set("rules",safeJson(json,db.list("SELECT f.* FROM asp_event_field f JOIN asp_competition_unit u ON u.event_id=f.event_id JOIN asp_registration r ON r.unit_id=u.id WHERE r.id=? ORDER BY f.id",id)));return n;}
 public JsonNode execute(String c,JsonNode in){if(c.equals("registration.mine"))return preview(c,in);if(c.equals("registration.create")){var e=registrations.createDraft(id(in,"unitId"),ActionContext.current().requestKey(),optionalId(in,"teamId"));return reference(json,"registrationId",e.id(),"draft");}long id=id(in,"registrationId");preview(c,in);var row=db.one("SELECT version FROM asp_registration WHERE id=? FOR UPDATE",id);if(number(row.get("version"))!=in.path("expectedVersion").asLong(-1))throw fail("名单或报名状态已变化，请重新核对",409);var card=registrations.listMine(null).stream().filter(r->r.id().equals(id)).findFirst().orElseThrow();var e=registrations.submit(id,card.requestKeyConsumed()?ActionContext.current().requestKey():card.requestKey());db.update("UPDATE asp_team_room SET status='submitted',version=version+1,update_time=CURRENT_TIMESTAMP WHERE registration_id=? AND status IN('forming','ready')",id);return reference(json,"registrationId",e.id(),e.status());}
}
